[
  {
    "id": "top-five-2000s",
    "source": "Most-viewed: 2000 - 2009\n#1 T-mac's 13 points in 33 seconds (Dec 9, 2004 - 27M views)\n#2 Kobe scores 81 (Jan 22, 2006 - 22M views)\n#3 Jordan ball fakes (Apr 7, 2003 – 9.4M views)\n#4 Fisher's 0.4 second game-winner (May 13, 2004 – 7.8M views)\n#5 Iverson steps over Lue (Jun 6, 2001 – 6M views)",
    "claim": "The five most-viewed 2000s moments by aggregated views are Tracy McGrady scoring 13 points in 33 seconds (27,179,256), Kobe's 81-point game (21,625,200), Jordan's ball fake (9,377,700), Derek Fisher's 0.4-second game-winner (7,822,632) and Allen Iverson stepping over Tyronn Lue (6,029,208).",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 2000].nlargest(5, 'agg_view_count').reset_index(drop=True).assign(rank=lambda d: d.index + 1)[['rank', 'title_custom', 'players', 'agg_view_count']]"
  },
  {
    "id": "top-five-1990s",
    "source": "Most-viewed: 1990 - 1999\n#1 Jordan's last 3 minutes as a Bull (Jun 14, 1998 - 35M views)\n#2 Jordan blocks Shaq in first meeting (Jan 12, 1993 - 12M views)\n#3 Shaq brings down the backboard (Apr 23, 1993 – 11M views)\n#4 Jordan's eyes-closed free-throw (Nov 23, 1991 – 6.5M views)\n#5 Jordan's \"Flu Game\" (Jun 11, 1997 – 6.5M views)",
    "claim": "The five most-viewed 1990s moments by aggregated views are Jordan's last 3 minutes as a Bull (34,843,786), Jordan blocking Shaq in their first meeting (11,990,355), Shaq bringing down the backboard (10,604,507), Jordan's eyes-closed free-throw (6,491,582) and Jordan's Flu Game (6,475,361).",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 1990].nlargest(5, 'agg_view_count').reset_index(drop=True).assign(rank=lambda d: d.index + 1)[['rank', 'title_custom', 'players', 'agg_view_count']]"
  },
  {
    "id": "top-five-1980s",
    "source": "Most-viewed: 1980 - 1989\n#1 The Shot (May 7, 1989 - 5.8M views)\n#2 Jordan scores 63 (Apr 20, 1986 - 3.2M views)\n#3 Bird steals pass for game-winner (May 26, 1987 – 2M views)\n#4 Bird scores 60 vs. Hawks (Mar 12, 1985 – 1.8M views)\n#5 Jordan's first 40-point game (Nov 13, 1984 – 1.2M views)",
    "claim": "The five most-viewed 1980s moments by aggregated views are The Shot by Jordan (5,756,462), Jordan scoring 63 in his first playoffs (3,178,044), Bird stealing the pass for a game-winner (1,958,433), Bird scoring 60 against the Hawks (1,780,790) and Jordan's first 40-point game (1,186,732).",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 1980].nlargest(5, 'agg_view_count').reset_index(drop=True).assign(rank=lambda d: d.index + 1)[['rank', 'title_custom', 'players', 'agg_view_count']]"
  },
  {
    "id": "all-time-most-viewed",
    "source": "It has more views than any other NBA moment in our dataset (i.e., it's #1, all-time, at 35M views).",
    "claim": "The most-viewed moment in the whole dataset is Jordan's last 3 minutes as a Bull, with 34,843,786 aggregated views.",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c.nlargest(1, 'agg_view_count')[['title_custom', 'players', 'agg_view_count']]"
  },
  {
    "id": "reggie-miller-sixth-1990s",
    "source": "And we're very disappointed to see Reggie's 8 points in 9 seconds outside the top 5 (it's #6).",
    "claim": "Reggie Miller's 8 points in 9 seconds ranks sixth among the 1990s moments by aggregated views, with 5,155,258.",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 1990].nlargest(100, 'agg_view_count').reset_index(drop=True).assign(rank=lambda d: d.index + 1).loc[lambda d: d.title_custom.str.contains('8 points in 9 seconds'), ['rank', 'title_custom', 'agg_view_count']]"
  },
  {
    "id": "jordan-majority-1990s",
    "source": "More than half of the plays are Jordan highlights.",
    "claim": "Jordan is named in 52 of the 100 most-viewed 1990s moments' labels, more than half.",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 1990].nlargest(100, 'agg_view_count').assign(Jordan=lambda d: d.title_custom.str.contains('Jordan', case=False)).Jordan.agg(['sum', 'count'])"
  },
  {
    "id": "one-ewing-highlight-1990s",
    "source": "It's criminal that there's only one Ewing highlight, and it's him on the receiving end of a Jordan dunk",
    "claim": "Exactly one of the 100 most-viewed 1990s moments is an Ewing highlight.",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 1990].nlargest(100, 'agg_view_count').assign(Ewing=lambda d: d.title_custom.str.contains('Ewing', case=False)).Ewing.agg(['sum', 'count'])"
  },
  {
    "id": "jordan-three-of-top-five-1980s",
    "source": "Unsurprisingly, 3 of the top 5 are Jordan.",
    "claim": "Three of the five most-viewed 1980s moments are Jordan highlights.",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 1980].nlargest(5, 'agg_view_count').assign(Jordan=lambda d: d.title_custom.str.contains('Jordan', case=False)).Jordan.agg(['sum', 'count'])"
  },
  {
    "id": "expert-list-ranks-1980s",
    "source": "They pointed to moments such as Ralph Sampson's game-winner (#26), Tree Bites Man (#31), or The Sleepy Floyd Game (#42), not Jordan's first 40-point game (#5).",
    "claim": "In the 1980s ranking, Jordan's first 40-point game is 5th, Ralph Sampson's game-winner is 26th, Tree Bites Man is 31st and The Sleepy Floyd Game is 42nd.",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c[c.decade == 1980].sort_values('agg_view_count', ascending=False).reset_index(drop=True).assign(rank=lambda d: d.index + 1).loc[lambda d: d.title_custom.str.contains('Ralph Sampson hits game-winner|Tree Bites Man|The Sleepy Floyd Game|first 40-point'), ['title_custom', 'players', 'rank']]"
  },
  {
    "id": "no-pre-1985-in-all-time-top-100",
    "source": "We barely found any videos in our top 100 from pre-Jordan era (‘80 - ‘84).",
    "claim": "The oldest of the 100 most-viewed moments in the dataset is from March 12, 1985; none predates 1985.",
    "tables": {
      "c": "data/curated_merged_by_decade.csv"
    },
    "code": "c.nlargest(100, 'agg_view_count').date.agg(['min', 'max', 'count'])"
  }
]

